import * as React from "react";
import { cx } from "./cx";

export interface NativeSelectProps extends React.SelectHTMLAttributes<HTMLSelectElement> {
  label?: React.ReactNode;
}

/** The platform list. Raster chrome. */
export const NativeSelect = React.forwardRef<HTMLSelectElement, NativeSelectProps>(
  function NativeSelect({ label, className, id, children, ...props }, ref) {
    const autoId = React.useId();
    const selectId = id ?? autoId;
    const control = (
      <select ref={ref} id={selectId} className={cx("rs-native-select", className)} {...props}>
        {children}
      </select>
    );
    if (label == null) return control;
    return (
      <div className="rs-field">
        <label className="rs-field-label" htmlFor={selectId}>
          {label}
        </label>
        {control}
      </div>
    );
  },
);

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Native select: the platform list, Raster chrome ── */
.rs-native-select{appearance:none;box-sizing:border-box;height:var(--control-h);font-family:inherit;font-size:14px;font-weight:500;letter-spacing:-.01em;line-height:calc(var(--control-h) - 2px);color:var(--text);background:var(--bg) url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' width='16' height='16' fill='none' stroke='%231A1A1A' stroke-width='1' stroke-linecap='butt' stroke-linejoin='miter'><g transform='rotate(90 8 8)'><path d='M5.5 3.5 L10.5 8 L5.5 12.5' vector-effect='non-scaling-stroke'/></g></svg>") no-repeat right 10px center;border:1px solid var(--divider);border-radius:var(--radius-sm);padding:0 32px 0 10px;outline:none;width:100%}
.rs-native-select:focus{border-color:var(--accent)}
[data-theme="dark"] .rs-native-select{background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' width='16' height='16' fill='none' stroke='%23E8E8E8' stroke-width='1' stroke-linecap='butt' stroke-linejoin='miter'><g transform='rotate(90 8 8)'><path d='M5.5 3.5 L10.5 8 L5.5 12.5' vector-effect='non-scaling-stroke'/></g></svg>")}
